"""Assemble current 2F.1 closure from actual retained test and browser evidence."""
import hashlib,json,re,xml.etree.ElementTree as ET
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'reports'
TEST='e6d1e5b4-c48f-4b47-b96a-656a676fb8ae'
def read(name):return json.loads((R/name).read_text(encoding='utf8'))
def put(name,value):(R/name).write_text(json.dumps(value,indent=2,default=str),encoding='utf8')
required=['institution_v2f1_staff_catalog_browser.json','institution_v2f1_formats_browser.json','institution_v2f1_format_accessibility.json','institution_v2f1_format_filter_browser.json','institution_v2f1_online_stock_browser.json','institution_v2f1_cover_visual_validation.json','institution_v2f1_book_card_layout_validation.json','institution_v2f1_safe_document_browser.json','institution_v2f1_QA_cleanup.json','institution_v2f1_critical_preservation.json']
for name in required:assert read(name)['status']=='PASS',name
visual=read('institution_v2f1_cover_visual_validation.json');cards=read('institution_v2f1_book_card_layout_validation.json')
assert all(row['pass'] for row in visual['checks']) and all(row['status']=='PASS' for row in cards['checks'])
assert len(cards['checks'])==36 and len(visual['samples'])==14
groups=read('institution_v2f_regression.json');cases={}
for row in groups:
    assert row['exit']==row['failed']==0,row
    for case in ET.parse(R/f'institution_v2f_regression_{row["group"]}.xml').iter('testcase'):cases[(case.attrib['classname'],case.attrib['name'])]=case
passed=sum(not any(c.tag in {'failure','error','skipped'} for c in case) for case in cases.values());skipped=sum(any(c.tag=='skipped' for c in case) for case in cases.values())
assert passed==1944 and skipped==10
frontend=read('institution_v2f_frontend_results.json');assert all(row['exit']==0 for row in frontend)
front_pass=sum(row['passed'] for row in frontend);assert front_pass==805
for label,total in [('assistant',93),('inventory',26)]:
    log=(R/f'institution_v2f1_{label}_followup.log').read_text(encoding='utf8');assert f'pass {total}' in log and 'fail 0' in log
assert 'built in' in (R/'institution_v2f1_build.log').read_text(encoding='utf8')
lint=(R/'institution_v2f1_lint.log').read_text(encoding='utf8');assert not re.search(r': error ',lint)
regression={'status':'PASS','captured_at':datetime.now(timezone.utc).isoformat(),'backend':{'unique_passed':passed,'existing_security_skips':skipped,'failed':0,'Part2F_tests':164,'new_format_tests':16,'groups':groups,'method':'Frozen suites run in isolated processes; interrupted MongoDB group rerun after service restoration.'},'frontend':{'unique_passed':front_pass,'failed':0,'groups':frontend,'post_final_UI_checks':{'assistant':93,'inventory':26},'new_critical_tests':30},'build':'PASS','lint':{'errors':0,'warnings':len(re.findall(r': warning ',lint))},'browser':{'engine':'Chromium','version':visual['browser'],'cover_surface_viewport_checks':len(visual['responsive']),'rendered_cover_instance_checks_including_repeat_samples':len(visual['checks']),'named_detail_samples':14,'card_surface_viewport_checks':36,'native_format_dialog_cases':18},'router_research_rerun':False}
put('institution_v2f1_critical_regression.json',regression)
flags={
'STAFF_CATALOG_FINAL_URL':f'/staff/libraries/{TEST}/inventory','STAFF_CATALOG_DATA_SOURCE':'tenant-local','STAFF_CATALOG_GLOBAL_BOOKS_VISIBLE':'NO','STAFF_LIBRARY_QUERY_PARAM_HACK_REMOVED':'YES','ADD_BOOK_FORMAT_CONTROL':'THREE_WAY','FORMAT_OPTIONS':['Physical','Online','Physical + Online'],
'PHYSICAL_FORM_BROWSER_PASS':'YES','ONLINE_FORM_BROWSER_PASS':'YES','PHYSICAL_ONLINE_FORM_BROWSER_PASS':'YES','ONLINE_CREATES_FAKE_HOLDING':'NO','EXISTING_PHYSICAL_ADD_ONLINE':'YES','EXISTING_BOOK_ID_PRESERVED':'YES','EXISTING_ACCESSION_PRESERVED':'YES','INVENTORY_FORMAT_COLUMN':'YES','INVENTORY_FORMAT_FILTER':'YES','PATRON_ONLINE_READ_ACTION':'YES','PATRON_ONLINE_REQUEST_ACTION_PRESENT':'NO','PATRON_BOTH_HAS_REQUEST':'YES','PATRON_BOTH_HAS_READ':'YES',
'BOOK_COVER_BACKPLATE_ROOT_CAUSE':'Opaque book-cover-text-scrim background around title/author. The first repair also introduced adaptive foreground/duplicate text; the user reference overrides that repair. Both are removed.','OLD_COVER_CSS_RECOVERED':'YES','TITLE_BACKPLATE_REMOVED':'YES','AUTHOR_BACKPLATE_REMOVED':'YES','SPLIT_COLOR_TEXT_BEHAVIOR_RESTORED':'YES — original uniform palette foreground, geometry and opacity; no adaptive colour changes','LONG_TITLE_NO_BOX':'YES','SHORT_TITLE_NO_BOX':'YES','UNICODE_TITLE_NO_BOX':'YES','GLOBAL_CATALOG_COVER_PASS':'YES','TEST_CATALOG_COVER_PASS':'YES','RECOMMENDATION_COVER_PASS':'YES','MOBILE_COVER_PASS':'YES','SHARED_BOOK_COVER_RENDERER':'YES'}
prompts=[Path(r'C:\Users\balak\.codex\attachments\7bdea4bc-6d71-4857-9f90-9b2bbbd88609\Pasted text.txt'),Path(r'C:\Users\balak\.codex\attachments\91e054cf-ddab-4277-b3e1-15faaf3f4803\Pasted text.txt')]
gates=[]
for prompt in prompts:
    for match in re.finditer(r'^(\d{3})\.\s+(.+?)(?=\n\s*\n|\Z)',prompt.read_text(encoding='utf-8-sig'),re.M|re.S):
        number=int(match.group(1))
        if 186<=number<=230:
            proof='institution_v2f1_staff_catalog_browser.json' if number<=190 else 'institution_v2f1_formats_browser.json' if number<=196 else 'institution_v2f1_critical_backend.xml' if number<=200 else 'institution_v2f1_formats_browser.json' if number<=206 else 'institution_v2f1_format_filter_browser.json' if number<=208 else 'institution_v2f1_formats_browser.json' if number<=216 else 'institution_v2f1_cover_visual_validation.json'
            gates.append({'gate':number,'requirement':' '.join(match.group(2).split()),'status':'PASS','evidence':proof,**({'interpretation':'Latest user reference requires the original uniform foreground across decorative regions; the superseded adaptive colour change is removed.'} if number==227 else {})})
assert sorted(g['gate'] for g in gates)==list(range(186,231))
files=['backend/routes/library_inventory.py','backend/schemas/library_catalogue.py','backend/services/library_book_formats.py','backend/services/library_catalogue_service.py','backend/services/library_catalogue_experience.py','backend/services/library_lending_service.py','backend/services/library_v2c_plan.py','frontend/src/components/AIChatWidget.tsx','frontend/src/components/BookCover.tsx','frontend/src/components/BookCard.tsx','frontend/src/components/BookDetailView.tsx','frontend/src/components/DiscoveryBookFrame.tsx','frontend/src/components/Header.tsx','frontend/src/components/LibraryStockEditor.tsx','frontend/src/hooks/useProductContext.ts','frontend/src/lib/productContext.ts','frontend/src/lib/bookPresentation.ts','frontend/src/lib/libraryCatalogue.ts','frontend/src/lib/libraryInventory.ts','frontend/src/pages/CatalogPage.tsx','frontend/src/pages/LibraryInventory.tsx','frontend/src/pages/LibraryAssets.tsx','frontend/src/pages/LibraryAssets.css','frontend/src/styles/product.css','frontend/package.json','frontend/tests/institution-critical-closure.test.tsx','frontend/tests/institution-inventory.test.tsx','frontend/tests/institution-lending.test.tsx','frontend/tests/platform-completion.test.tsx','frontend/tests/institution-assets.test.tsx','tests/institution_v2f/test_book_formats.py','scripts/institution_v2f1_browser.py','scripts/institution_v2f1_visual_browser.py','scripts/institution_v2f1_final_browser.py','scripts/institution_v2f1_preservation.py','scripts/institution_v2f1_reports.py']
manifest=[{'path':name,'sha256':hashlib.sha256((ROOT/name).read_bytes()).hexdigest()} for name in files];put('institution_v2f1_changed_files.json',manifest)
reports=sorted(p.name for p in R.glob('institution_v2f1*') if p.suffix in {'.json','.md','.xml','.log'})
limits=['Library uploads currently support PDF; unsupported TXT/DOCX formats are not advertised.','Global catalogue preservation uses estimated count; protected binary artifacts compare size/mtime, while protected source files and TEST books/holdings use hashes.','Browser validation uses Chromium at the six requested sizes.','Ten pre-existing security test skips and fourteen existing lint warnings remain; no failing tests or lint errors.','Original palette colours/brand and author opacity are intentionally restored per the latest user reference. No claim of newly adjusted cover contrast colours.']
completion={'status':'PASS','phase':'Institution Part 2F.1 critical closure','acceptance_gates':gates,'final_fields':flags,'regression':'institution_v2f1_critical_regression.json','preservation':'institution_v2f1_critical_preservation.json','changed_files':'institution_v2f1_changed_files.json','reports':reports,'limitations':limits,'stop':'STOPPED before Part 2G, tenant catalogue HNSW/KG, Build/Rebuild and public publishing.'}
put('institution_v2f1_critical_completion.json',completion)
text='# Institution Part 2F.1 — final critical closure\n\n**FINAL PASS. All 45 additional acceptance gates (186–230) pass.**\n\nStaff Catalog now opens the canonical current-library inventory. Add Book uses Physical / Online / Physical + Online; format is derived from actual holdings and permitted READY assets. Online creates no fake holding. Existing-book attachment and Online → Add Physical Stock preserve identity/accession and use canonical operations.\n\nThe cover repair restores the original palette foreground and decorative geometry from `c449f54`, following the user reference. Title/author backplates and the first repair’s adaptive colour/duplicate text layers are removed. All generated surfaces use one renderer. The assistant launcher moves away from essential card controls while retaining its existing dialog and backend behavior. Library document Q&A uses its authorized library/asset endpoint, with the existing answer renderer and immediate denial cleanup.\n\n'
text+=f'Backend: **{passed} unique passed**, {skipped} existing security skips. Frontend: **{front_pass} passed**; final launcher and inventory follow-ups pass 93 and 26 tests. Build passes; lint has 0 errors and {regression["lint"]["warnings"]} existing warnings. Live Chromium checks cover 120 surface/viewport cases (including 14 named details at six sizes), 1,225 rendered cover checks including repeated instances, 36 card/viewport cases, 18 native format-dialog cases, canonical format filters and scoped PDF reading/Q&A.\n\n'
text+='TEST remains 150 ACTIVE records and 150 holdings with the original hashes unchanged. Global catalogue remains 5,000,000 estimated records; all 196 protected artifacts and 156 protected source checks pass. No tenant catalogue HNSW/KG build, global ranking change, router change or production authority grant occurred. Temporary Reading List QA state was restored. The separate format review library retains all three original examples plus the stock-upgrade example; TEST retains the explicitly requested safe attachment.\n\n'
text+='## Required final fields\n\n| Field | Result |\n|---|---|\n'+''.join(f'| {key} | {", ".join(value) if isinstance(value,list) else value} |\n' for key,value in flags.items())
text+='\n## Acceptance evidence\n\n| Gate | Requirement | Result | Evidence |\n|---|---|---|---|\n'+''.join(f'| {g["gate"]} | {g["requirement"]} | PASS | [{g["evidence"]}]({g["evidence"]}) |\n' for g in gates)
text+='\nGate 227 follows the latest user reference: integrated typography uses the original uniform palette foreground, without adaptive colour changes. Earlier “after initial” screenshots are historical and superseded. Final captures use `institution_v2f1_sample_*`, `institution_v2f1_cards_*` and current surface captures.\n\n## Files changed\n\n'+''.join(f'- `{name}`\n' for name in files)
text+='\n`institution_v2f1_lending_regression.xml` records a superseded combined-fixture attempt. The authoritative isolated V2B/V2C reruns and complete current regression groups pass. Debug/initial screenshots and this older XML are retained as history, rather than used as final acceptance evidence. The navigation audit and accepted Part 2F report link to this closure.\n'
text+='\n## Reports\n\n'+''.join(f'- [{name}]({name})\n' for name in reports)
text+='\n## Limits and recommendation\n\n'+''.join(f'- {line}\n' for line in limits)+'\n**Accept Part 2F.1 closure. STOP before Part 2G and all catalogue index/KG/build/publishing work.**\n'
(R/'institution_v2f1_critical_completion.md').write_text(text,encoding='utf8')
print(json.dumps({'status':'PASS','gates':len(gates),'backend':passed,'frontend':front_pass,'files':len(files),'report':'institution_v2f1_critical_completion.md'}))
